// Defines values for IssuingCardholderRequirementsDisabledReason.
const (
	IssuingCardholderRequirementsDisabledReasonListed              IssuingCardholderRequirementsDisabledReason = "listed"
	IssuingCardholderRequirementsDisabledReasonRejectedListed      IssuingCardholderRequirementsDisabledReason = "rejected.listed"
	IssuingCardholderRequirementsDisabledReasonRequirementsPastDue IssuingCardholderRequirementsDisabledReason = "requirements.past_due"
	IssuingCardholderRequirementsDisabledReasonUnderReview         IssuingCardholderRequirementsDisabledReason = "under_review"
)

// Valid indicates whether the value is a known member of the IssuingCardholderRequirementsDisabledReason enum.
func (e IssuingCardholderRequirementsDisabledReason) Valid() bool {
	switch e {
	case IssuingCardholderRequirementsDisabledReasonListed:
		return true
	case IssuingCardholderRequirementsDisabledReasonRejectedListed:
		return true
	case IssuingCardholderRequirementsDisabledReasonRequirementsPastDue:
		return true
	case IssuingCardholderRequirementsDisabledReasonUnderReview:
		return true
	default:
		return false
	}
}

